(() => {
  'use strict';
  const $ = (s, root=document) => root.querySelector(s);
  const $$ = (s, root=document) => [...root.querySelectorAll(s)];
  const UNIT_DATA = {
    yuji:{id:'yuji',name:'YUJI',full:'Yuji Itadori',rarity:'COMMON',grade:'GRADE 2',role:'BRAWLER',cost:120,color:'#ad4d52',glyph:'虎',damage:25,range:105,rate:.76,desc:'A close-range brawler who hits hard and fast.',attack:'Divergent Fist',stats:['ATK 25','RANGE 105','SPD FAST']},
    nobara:{id:'nobara',name:'NOBARA',full:'Nobara Kugisaki',rarity:'RARE',grade:'GRADE 3',role:'RANGED',cost:150,color:'#a65466',glyph:'釘',damage:20,range:175,rate:1.05,desc:'Nails curse targets from a safe distance.',attack:'Resonance',stats:['ATK 20','RANGE 175','SPD MED']},
    megumi:{id:'megumi',name:'MEGUMI',full:'Megumi Fushiguro',rarity:'RARE',grade:'GRADE 2',role:'SUMMONER',cost:180,color:'#4b6477',glyph:'影',damage:14,range:145,rate:1.35,desc:'Summons shikigami to harass a whole lane.',attack:'Divine Dogs',stats:['ATK 14','RANGE 145','SPD MED']},
    gojo:{id:'gojo',name:'GOJO',full:'Satoru Gojo',rarity:'SPECIAL GRADE',grade:'SPECIAL GRADE',role:'DOMAIN',cost:300,color:'#5b78a5',glyph:'無',damage:66,range:210,rate:1.2,desc:'The strongest. Infinity keeps curses at bay.',attack:'Limitless',stats:['ATK 66','RANGE 210','SPD MED']},
    maki:{id:'maki',name:'MAKI',full:'Maki Zenin',rarity:'RARE',grade:'GRADE 4',role:'ASSAULT',cost:145,color:'#557358',glyph:'真',damage:31,range:110,rate:.9,desc:'A weapon specialist with no cursed energy.',attack:'Playful Cloud',stats:['ATK 31','RANGE 110','SPD FAST']},
    panda:{id:'panda',name:'PANDA',full:'Panda',rarity:'COMMON',grade:'GRADE 2',role:'TANK',cost:135,color:'#69716a',glyph:'熊',damage:17,range:100,rate:1.1,desc:'A resilient corpse with a surprising punch.',attack:' Gorilla Mode',stats:['ATK 17','RANGE 100','SPD MED']},
    todo:{id:'todo',name:'TODO',full:'Aoi Todo',rarity:'RARE',grade:'GRADE 1',role:'SUPPORT',cost:175,color:'#866248',glyph:'拍',damage:24,range:130,rate:1,desc:'A powerful ally who hits curses with a clap.',attack:'Boogie Woogie',stats:['ATK 24','RANGE 130','SPD MED']}
  };
  const defaults = {coins:850,shards:120,owned:['yuji','nobara','megumi'],equipped:['yuji','nobara','megumi'],fragments:2,cells:0,evolved:[],clears:0};
  let save = load();
  function load(){try{return {...defaults,...JSON.parse(localStorage.getItem('cursedCircuitSave')||'{}')}}catch{return {...defaults}}}
  function persist(){localStorage.setItem('cursedCircuitSave',JSON.stringify(save));renderResources()}
  function renderResources(){$('#coin-count').textContent=save.coins.toLocaleString();$('#shard-count').textContent=save.shards.toLocaleString();$('#roster-owned').textContent=String(save.owned.length).padStart(2,'0');$('#cell-count').textContent=save.cells;$('#fragment-count').textContent=save.fragments;$('#forge-fragments').textContent=save.fragments}
  let mode='story', stage=0, game=null, selectedUnit=null, selectedPlaced=null, toastTimer;
  const storyStages=[{name:'CURSED PLATFORM',mission:'A CURSED<br>WELCOMING',desc:'A swarm of low-grade curses has breached the station. Clear the platform before the veil collapses.',waves:5,reward:180},{name:'UNDERPASS AMBUSH',mission:'NO WAY<br>BACK',desc:'The tunnel is sealed. Keep moving and protect the civilians caught in the veil.',waves:6,reward:240},{name:'CURTAIN CALL',mission:'THE VEIL<br>THINS',desc:'A special grade presence is approaching. The last line of defense starts here.',waves:7,reward:340}];
  function stageInfo(){return mode==='boss'?{name:'SPECIAL GRADE ARENA',mission:'CURSE<br>OF THE CENTURY',desc:'Three special grades stand between you and the dawn. Bring your strongest squad.',waves:3,reward:500}:storyStages[stage%storyStages.length]}
  function notify(msg){const t=$('#toast');t.textContent=msg;t.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>t.classList.remove('show'),2300)}
  function goView(name){$$('.view').forEach(v=>v.classList.toggle('active-view',v.id===`view-${name}`));$$('.nav-btn').forEach(b=>b.classList.toggle('active',b.dataset.view===name));$('.main-nav').classList.remove('open');if(name==='units')renderRoster();if(name==='forge')renderForge();if(name==='battle')renderDeploy();}
  $$('[data-view]').forEach(b=>b.addEventListener('click',e=>{e.preventDefault();goView(b.dataset.view)}));$('.mobile-menu').addEventListener('click',()=>$('.main-nav').classList.toggle('open'));
  $$('.mode-option').forEach(b=>b.addEventListener('click',()=>{mode=b.dataset.mode;$$('.mode-option').forEach(x=>x.classList.toggle('selected',x===b));stage=0;updateMission();resetBoard()}));
  $('#next-stage').addEventListener('click',()=>{if(mode==='boss'){notify('Boss Rush is a single operation.');return}stage=(stage+1)%storyStages.length;updateMission();resetBoard()});
  function updateMission(){const d=stageInfo();$('#mission-mode-label').textContent=mode==='boss'?'BOSS RUSH • OPERATION':`STORY MISSION 0${stage+1}`;$('#mission-title').innerHTML=d.mission;$('#mission-description').textContent=d.desc;$('#wave-total').textContent=String(d.waves).padStart(2,'0');$('#wave-count').textContent=d.waves;$('#stage-name').textContent=d.name;$('#wave-current').textContent='0';$('#wave-progress-fill').style.width='0%';$('#battle-state').textContent='STANDBY';$('#battle-state').classList.remove('live');$('#result-modal').classList.remove('show');$('#board-hint').style.opacity='1'}
  function renderDeploy(){let cards=$('#deployment-cards');cards.innerHTML='';const equipped=save.equipped.slice(0,4);$('#squad-count').textContent=`${equipped.length} / 4`;equipped.forEach(id=>{const u=UNIT_DATA[id];if(!u)return;const card=document.createElement('button');card.className='deploy-card'+(selectedUnit===id?' selected':'');card.innerHTML=`<span class="unit-avatar" style="--avatar:${u.color}"><span>${u.glyph}</span></span><span class="unit-info"><b>${u.name}</b><small>${u.role}</small><em>${u.cost} ¥</em></span><span class="cost-tag">✦</span>`;card.addEventListener('click',()=>{selectedUnit=selectedUnit===id?null:id;selectedPlaced=null;renderDeploy();if(selectedUnit){$('#inspector-title').textContent=`${u.full.toUpperCase()} • ${u.attack.toUpperCase()}`;$('#inspector-description').textContent='Tap a glowing tile on the field to deploy this sorcerer.';$('#upgrade-unit').disabled=true;$('#sell-unit').disabled=true;$('#board-hint').style.opacity='1'}});cards.append(card)});for(let i=equipped.length;i<4;i++){const blank=document.createElement('div');blank.className='deploy-card locked';blank.innerHTML='<span class="unit-avatar"><span>?</span></span><span class="unit-info"><b>OPEN SLOT</b><small>Equip a sorcerer</small></span>';cards.append(blank)}}
  function renderRoster(){const root=$('#roster-grid');root.innerHTML='';Object.values(UNIT_DATA).forEach(u=>{const has=save.owned.includes(u.id),equipped=save.equipped.includes(u.id);const card=document.createElement('article');card.className='roster-card'+(!has?' locked-roster':'');card.innerHTML=`<div class="roster-art" style="--avatar:${u.color}"><small class="rarity">${has?u.rarity:'???'}</small><span>${has?u.glyph:'?'}</span></div><div class="roster-details"><small class="grade">${has?u.grade:'UNDISCOVERED'}</small><h3>${has?u.full:'UNKNOWN SORCERER'}</h3><p>${has?u.desc:'Recruit new sorcerers to reveal their techniques.'}</p><div class="roster-stats">${has?u.stats.map(s=>`<span>${s.split(' ')[1]}<small>${s.split(' ')[0]}</small></span>`).join(''):'<span>???<small>TECHNIQUE</small></span>'}</div>${has?`<button class="equip-toggle ${equipped?'equipped':''}">${equipped?'✓ EQUIPPED':'+ EQUIP'}</button>`:''}</div>`;const toggle=$('.equip-toggle',card);if(toggle)toggle.addEventListener('click',()=>{if(equipped){if(save.equipped.length===1){notify('Your squad needs at least one sorcerer.');return}save.equipped=save.equipped.filter(x=>x!==u.id)}else{if(save.equipped.length>=4){notify('Squad full. Remove a sorcerer first.');return}save.equipped.push(u.id)}persist();renderRoster()});root.append(card)});renderResources()}
  function drawRecruit(n){const pool=['gojo','maki','panda','todo','nobara','megumi','yuji'];let gained=[];for(let i=0;i<n;i++){let id;if(n>1&&i===n-1&&!gained.some(x=>x==='gojo')&&!save.owned.includes('gojo'))id='gojo';else id=pool[Math.floor(Math.random()*pool.length)];if(save.owned.includes(id)){save.shards+=id==='gojo'?55:35;gained.push(`${UNIT_DATA[id].name} shards`)}else{save.owned.push(id);save.shards+=15;gained.push(UNIT_DATA[id].name)}}persist();renderRoster();notify(n===1?`Recruit acquired: ${gained[0]}!`:`Recruitment complete: ${gained.slice(0,3).join(', ')}${gained.length>3?' + more':''}`)}
  $$('[data-pull]').forEach(b=>b.addEventListener('click',()=>{const n=Number(b.dataset.pull),cost=n===10?1350:150;if(save.shards<cost){notify('Not enough shards. Clear a mission or craft your way up.');return}save.shards-=cost;drawRecruit(n)}));
  $$('.forge-tab').forEach(b=>b.addEventListener('click',()=>{$$('.forge-tab').forEach(x=>x.classList.toggle('active',x===b));$$('.forge-content').forEach(x=>x.classList.toggle('active',x.id===`forge-${b.dataset.forge}`));if(b.dataset.forge==='evolve')renderEvolve()}));
  $('#craft-cell').addEventListener('click',()=>{if(save.coins<100||save.shards<40){notify('You need 100 coins and 40 shards to craft.');return}save.coins-=100;save.shards-=40;save.cells++;persist();notify('Cursed Energy Cell crafted.');renderForge()});
  function renderForge(){renderResources();renderEvolve()}
  function renderEvolve(){const root=$('#evolve-list');if(!root)return;root.innerHTML='';save.owned.forEach(id=>{const u=UNIT_DATA[id];if(!u)return;const row=document.createElement('div');row.className='evolve-row';const can=save.cells>0&&save.fragments>=2&&!save.evolved.includes(id);row.innerHTML=`<span class="unit-avatar" style="--avatar:${u.color}"><span>${u.glyph}</span></span><div><b>${u.full}</b><small>${save.evolved.includes(id)?'TECHNIQUE AWAKENED':'2 FRAGMENTS + 1 ENERGY CELL'}</small></div><button ${can?'':'disabled'}>${save.evolved.includes(id)?'AWAKENED':'EVOLVE'}</button>`;$('button',row).addEventListener('click',()=>{if(!can)return;save.cells--;save.fragments-=2;save.evolved.push(id);persist();renderEvolve();notify(`${u.name}'s technique has evolved!`)});root.append(row)})}

  const canvas=$('#game-canvas'),ctx=canvas.getContext('2d');const W=900,H=500,cell=50;
  const pathBase=[[0,145],[185,145],[185,75],[390,75],[390,265],[610,265],[610,125],[900,125]];
  let path=pathBase.map(p=>[p[0],p[1]]),placements=[],enemies=[],shots=[],particles=[],spawnTimer=0,spawned=0,wave=0,gameTime=0,acc=0,paused=false,speed=1,last=0,domainCharge=0;
  function resetBoard(){game=null;placements=[];enemies=[];shots=[];particles=[];wave=0;spawned=0;paused=false;speed=1;domainCharge=0;selectedUnit=null;selectedPlaced=null;$('#pause-btn').innerHTML='Ⅱ <small>PAUSE</small>';$('#speed-btn').innerHTML='» <small>1×</small>';$('#domain-charge').textContent='0%';$('#domain-btn').disabled=true;$('#lives').innerHTML='<i>♥</i><i>♥</i><i>♥</i><i>♥</i><i>♥</i>';updateMission();renderDeploy();draw()}
  function resize(){const rect=canvas.getBoundingClientRect();const dpr=Math.min(devicePixelRatio||1,2);canvas.width=Math.round(rect.width*dpr);canvas.height=Math.round(rect.height*dpr);ctx.setTransform(canvas.width/W,0,0,canvas.height/H,0,0);draw()};new ResizeObserver(resize).observe(canvas);
  function startGame(){const info=stageInfo();game={active:true,over:false,lives:5,coins:save.coins,mode,waves:info.waves,reward:info.reward,intermission:false};save.coins=save.coins;placements=[];enemies=[];shots=[];particles=[];wave=0;spawned=0;spawnTimer=0;gameTime=0;domainCharge=0;paused=false;speed=1;$('#result-modal').classList.remove('show');$('#board-hint').style.opacity='0';$('#battle-state').textContent='DEPLOYING';$('#battle-state').classList.add('live');$('#domain-btn').disabled=true;$('#domain-charge').textContent='0%';$('#pause-btn').innerHTML='Ⅱ <small>PAUSE</small>';renderDeploy();beginWave();last=performance.now();requestAnimationFrame(loop)}
  function beginWave(){wave++;spawned=0;game.intermission=false;spawnTimer=.45;$('#wave-current').textContent=String(wave);$('#wave-progress-fill').style.width=`${((wave-1)/game.waves)*100}%`;const toast=$('#wave-toast');toast.textContent=game.mode==='boss'?`BOSS ${wave} INCOMING`:`WAVE ${String(wave).padStart(2,'0')}`;toast.classList.add('show');setTimeout(()=>toast.classList.remove('show'),1050);}
  $('#start-battle').addEventListener('click',()=>{if(game?.active&&!game.over){notify('Operation already in progress.');return}startGame()});
  $('#pause-btn').addEventListener('click',()=>{if(!game?.active)return;paused=!paused;$('#pause-btn').innerHTML=paused?'▶ <small>RESUME</small>':'Ⅱ <small>PAUSE</small>';$('#battle-state').textContent=paused?'PAUSED':'LIVE';if(!paused){last=performance.now();requestAnimationFrame(loop)}});
  $('#speed-btn').addEventListener('click',()=>{speed=speed===1?2:1;$('#speed-btn').innerHTML=`» <small>${speed}×</small>`});
  $('#domain-btn').addEventListener('click',()=>{if(domainCharge<100)return;domainCharge=0;$('#domain-charge').textContent='0%';$('#domain-btn').disabled=true;enemies.forEach(e=>{e.hp-=125;e.slow=1.5;burst(e.x,e.y,'#9b85e9',14)});notify('DOMAIN EXPANSION: CURSED FIELD!')});
  function spawnEnemy(){const boss=game.mode==='boss'||(wave===game.waves&&spawned===Math.floor(waveCount()/2));const isBoss=game.mode==='boss'||boss;const hp=(game.mode==='boss'?250:32+wave*13)*(isBoss?1.35:1);enemies.push({x:path[0][0],y:path[0][1],seg:0,t:0,hp,max:hp,speed:isBoss?25:40+wave*2,boss:isBoss,size:isBoss?20:10,reward:isBoss?45:9,slow:0,phase:Math.random()*6.28});spawned++}
  function waveCount(){return game.mode==='boss'?2:5+wave}
  function beginWaveIfReady(dt){if(spawned<waveCount()){spawnTimer-=dt;if(spawnTimer<=0){spawnEnemy();spawnTimer=game.mode==='boss'?1.5:Math.max(.35,1.05-wave*.07)}}else if(enemies.length===0){if(wave>=game.waves){finish(true);return}game.intermission=true;$('#battle-state').textContent='WAVE CLEAR';setTimeout(()=>{if(game?.active&&!game.over&&!paused&&game.intermission)beginWave()},850)}}
  function loop(now){if(!game?.active||game.over||paused)return;const dt=Math.min(.05,(now-last)/1000)*speed;last=now;gameTime+=dt;acc+=dt;simulate(dt);draw();requestAnimationFrame(loop)}
  function simulate(dt){if(game.intermission){beginWaveIfReady(dt);return}beginWaveIfReady(dt);if(game.over)return;for(let i=enemies.length-1;i>=0;i--){const e=enemies[i];if(e.hp<=0){save.coins+=e.reward;domainCharge=Math.min(100,domainCharge+(e.boss?17:4));burst(e.x,e.y,e.boss?'#edb75f':'#e26f82',e.boss?18:7);enemies.splice(i,1);continue}if(e.slow>0)e.slow=Math.max(0,e.slow-dt);const speedE=e.speed*(e.slow>0?.5:1);const [ax,ay]=path[e.seg],[bx,by]=path[e.seg+1];const len=Math.hypot(bx-ax,by-ay);e.t+=speedE*dt/len;if(e.t>=1){e.seg++;e.t=0;if(e.seg>=path.length-1){enemies.splice(i,1);game.lives--;updateLives();if(game.lives<=0){finish(false);return}continue}}const p=path[e.seg],q=path[e.seg+1];e.x=p[0]+(q[0]-p[0])*e.t;e.y=p[1]+(q[1]-p[1])*e.t;e.phase+=dt*3}
    for(const tower of placements){tower.cool-=dt;if(tower.cool<=0){const u=UNIT_DATA[tower.id],range=u.range*(tower.level>1?1.1:1);const target=enemies.filter(e=>Math.hypot(e.x-tower.x,e.y-tower.y)<range).sort((a,b)=>b.seg+b.t-(a.seg+a.t))[0];if(target){tower.cool=u.rate*(tower.level>1?.75:1);shots.push({x:tower.x,y:tower.y-14,target,damage:u.damage*(tower.level>1?1.8:1),color:u.color,life:1.3})}}}
    for(let i=shots.length-1;i>=0;i--){const s=shots[i];if(!enemies.includes(s.target)){shots.splice(i,1);continue}const dx=s.target.x-s.x,dy=s.target.y-s.y,d=Math.hypot(dx,dy),step=dt*560;if(d<step){s.target.hp-=s.damage;burst(s.target.x,s.target.y,s.color,3);shots.splice(i,1)}else{s.x+=dx/d*step;s.y+=dy/d*step;s.life-=dt;if(s.life<=0)shots.splice(i,1)}}for(let i=particles.length-1;i>=0;i--){const p=particles[i];p.x+=p.vx*dt;p.y+=p.vy*dt;p.life-=dt;if(p.life<=0)particles.splice(i,1)}$('#domain-charge').textContent=`${Math.floor(domainCharge)}%`;$('#domain-btn').disabled=domainCharge<100;$('#wave-progress-fill').style.width=`${((wave-1+spawned/waveCount())/game.waves)*100}%`;}
  function updateLives(){const hearts=$$('#lives i');hearts.forEach((h,i)=>h.classList.toggle('off',i>=game.lives));}
  function finish(win){game.over=true;game.active=false;$('#battle-state').textContent=win?'CLEARED':'BREACHED';$('#battle-state').classList.remove('live');const modal=$('#result-modal');modal.classList.add('show');$('#result-stamp').textContent=win?'MISSION CLEARED':'VEIL BREACHED';$('#result-title').textContent=win?'PLATFORM SECURED':'CURSES OVERRAN THE VEIL';$('#result-copy').textContent=win?'The veil holds. The city owes you one.':'The sorcerers retreat to regroup. Try a different formation.';const coinReward=win?game.reward:Math.max(20,wave*12);save.coins+=coinReward;if(win){save.fragments+=1;save.clears++;}save.coins=Math.floor(save.coins);persist();$('#result-rewards').textContent=win?`+${coinReward} ¥  •  +1 CURSE FRAGMENT`:`+${coinReward} ¥`;$('#result-continue').textContent=win?'CONTINUE':'RETRY';$('#result-continue').onclick=()=>{modal.classList.remove('show');if(win){if(mode==='story')stage=(stage+1)%storyStages.length;updateMission();resetBoard()}else startGame()};renderDeploy()}
  function burst(x,y,color,n){for(let i=0;i<n;i++){const a=Math.random()*Math.PI*2,v=20+Math.random()*65;particles.push({x,y,vx:Math.cos(a)*v,vy:Math.sin(a)*v,life:.25+Math.random()*.35,max:.6,color})}}
  function pathDistance(x,y){let best=999;for(let i=0;i<path.length-1;i++){const [x1,y1]=path[i],[x2,y2]=path[i+1],dx=x2-x1,dy=y2-y1,t=Math.max(0,Math.min(1,((x-x1)*dx+(y-y1)*dy)/(dx*dx+dy*dy)));best=Math.min(best,Math.hypot(x-(x1+t*dx),y-(y1+t*dy)))}return best}
  function tileAllowed(x,y){return x>22&&x<W-20&&y>20&&y<H-20&&pathDistance(x,y)>45&&!placements.some(p=>Math.hypot(x-p.x,y-p.y)<46)}
  canvas.addEventListener('pointerdown',e=>{const rect=canvas.getBoundingClientRect(),x=(e.clientX-rect.left)/rect.width*W,y=(e.clientY-rect.top)/rect.height*H;const placed=placements.find(p=>Math.hypot(x-p.x,y-p.y)<24);if(placed){selectedPlaced=placed;selectedUnit=null;renderDeploy();showPlaced(placed);draw();return}if(!selectedUnit){return}const gx=Math.round(x/cell)*cell,gy=Math.round(y/cell)*cell;if(!tileAllowed(gx,gy)){notify('That tile is too close to the curse path.');return}if(save.coins<UNIT_DATA[selectedUnit].cost){notify('Not enough coins to deploy this sorcerer.');return}save.coins-=UNIT_DATA[selectedUnit].cost;placements.push({id:selectedUnit,x:gx,y:gy,cool:.25,level:1});persist();selectedUnit=null;renderDeploy();$('#inspector-title').textContent='SORCERER DEPLOYED';$('#inspector-description').textContent='Tap a deployed sorcerer to upgrade or recall.';draw()});
  function showPlaced(p){const u=UNIT_DATA[p.id];selectedPlaced=p;$('#inspector-title').textContent=`${u.full.toUpperCase()} • LV.${p.level}`;$('#inspector-description').textContent=`${u.attack} • ${p.level>1?'Awakened technique':'Tap upgrade to increase damage'}`;const cost=p.level===1?80:150;$('#upgrade-cost').textContent=cost;$('#upgrade-unit').disabled=!game?.active||p.level>=3||save.coins<cost;$('#sell-unit').disabled=!game?.active}
  $('#upgrade-unit').addEventListener('click',()=>{if(!selectedPlaced||!game?.active)return;const cost=selectedPlaced.level===1?80:150;if(selectedPlaced.level>=3||save.coins<cost){notify('Not enough coins or max level reached.');return}save.coins-=cost;selectedPlaced.level++;persist();showPlaced(selectedPlaced);notify('Sorcerer technique upgraded!')});$('#sell-unit').addEventListener('click',()=>{if(!selectedPlaced||!game?.active)return;save.coins+=Math.floor(UNIT_DATA[selectedPlaced.id].cost*.65);placements=placements.filter(p=>p!==selectedPlaced);selectedPlaced=null;persist();$('#inspector-title').textContent='UNIT RECALLED';$('#inspector-description').textContent='Tap a unit card, then choose another tile.';$('#upgrade-unit').disabled=true;$('#sell-unit').disabled=true;draw()});
  function draw(){if(!ctx)return;ctx.clearRect(0,0,W,H);const bg=ctx.createLinearGradient(0,0,W,H);bg.addColorStop(0,'#1c1c23');bg.addColorStop(1,'#111319');ctx.fillStyle=bg;ctx.fillRect(0,0,W,H);drawBackground();drawPath();if(selectedUnit){for(let y=25;y<H;y+=cell)for(let x=25;x<W;x+=cell){if(tileAllowed(x,y)){ctx.fillStyle='rgba(232,179,93,.035)';ctx.fillRect(x-19,y-19,38,38);ctx.strokeStyle='rgba(232,179,93,.17)';ctx.strokeRect(x-19,y-19,38,38)}}}
    placements.forEach(p=>drawTower(p));enemies.forEach(drawEnemy);shots.forEach(drawShot);particles.forEach(drawParticle);drawStartEnd();}
  function drawBackground(){ctx.save();for(let x=0;x<W;x+=50)for(let y=0;y<H;y+=50){ctx.fillStyle=((x/50+y/50)%2===0)?'#ffffff04':'#00000004';ctx.fillRect(x+1,y+1,48,48)}for(let i=0;i<20;i++){const x=(i*173+31)%W,y=(i*97+53)%H;if(pathDistance(x,y)>70){ctx.fillStyle='#ded9df0c';ctx.beginPath();ctx.arc(x,y,1.3,0,Math.PI*2);ctx.fill()}}ctx.strokeStyle='#e3b06714';ctx.lineWidth=1;ctx.beginPath();ctx.arc(783,415,73,0,Math.PI*2);ctx.stroke();ctx.beginPath();ctx.arc(783,415,54,0,Math.PI*2);ctx.stroke();ctx.fillStyle='#e3b06712';ctx.font='20px serif';ctx.fillText('呪',774,422);ctx.restore()}
